# Physiology quizzes by organ (Nov 2026). Each question: Q(q, correct, [3 wrong], why). Builder shuffles.
def Q(q, a, w, why):
    return dict(q=q, a=a, w=w, why=why)

def Z(slug, emoji, name, card, qs, faqs):
    how = "How Teeth Work" if name == "Teeth" else "How the %s Works" % name
    howl = "how teeth work" if name == "Teeth" else "how the %s works" % name.lower()
    return dict(slug=slug, emoji=emoji, h1="%s Physiology Quiz" % name,
                title="%s Physiology Quiz: %s" % (name, how),
                desc="Free %s physiology quiz: %d questions on %s, with short explanations. Easy to hard." % (name.lower(), len(qs), card.rstrip(".").lower()),
                card=card, lede="%d questions on %s: %s Easy to hard. Tap an answer to see if you’re right." % (len(qs), howl, card[0].lower() + card[1:]),
                qs=qs, faqs=faqs)

